"""Category concept heroes and a factual careers introduction page."""
def division_hero(x,g):
    e,en=g['e'],g['en'];slug=x['slug']
    palette={'soft-play':('#eef0df','#c1d257'),'water-parks':('#e6f3f4','#9dd1d5'),'arcade-games':('#edf0e8','#b8ce79'),'amusement-park-equipment':('#fbf0db','#e3c477')}
    bg,accent=palette[slug]
    title=e(en(x['h1'][0]))+'<br>'+e(en(x['h1'][1]))
    return f'''<section class="division-hero" data-division-hero="{slug}" style="--division-bg:{bg};--division-accent:{accent}"><div class="division-hero-copy"><p>{e(en(x['kicker']))}</p><h1>{title}</h1><p class="division-hero-lede">{e(en(x['lede']))}</p><div class="p-actions"><a class="p-button" href="/contact/?type={g['quote'](x['ptype'])}">Let’s plan your space</a><a class="p-text-link" href="#lp-d">Explore the possibilities <span aria-hidden="true">↓</span></a></div></div><figure class="division-hero-visual"><div class="division-orbit" aria-hidden="true"></div><img src="/img/division-concepts/{slug}.webp" width="1536" height="1024" alt="AI-generated 3D-style concept for {e(en(x['kicker']))}" fetchpriority="high" decoding="async"><figcaption>AI-generated category concept. Equipment and layout are developed for your project.</figcaption></figure></section>'''

def build_careers(g):
    body='''<div class="careers-page"><section class="careers-hero"><p>Careers at Dupedia</p><h1>Your next chapter.<br>A little more playful.</h1><p class="careers-lede">Bring your curiosity, creativity and care. Help us imagine, make and deliver places that bring people together.</p><a class="p-button" href="#career-intro">Introduce yourself</a><div class="career-blocks" aria-hidden="true"><i></i><i></i><i></i><i></i></div></section>
    <section class="p-container careers-paths"><div><h2>Different talents.<br>One shared purpose.</h2><p>Explore where your experience could fit. These are areas of work, rather than advertised vacancies.</p></div><ul><li><span>Design & planning</span><p>Ideas, layouts and thoughtful play experiences.</p></li><li><span>Engineering & making</span><p>Technical thinking, materials and craftsmanship.</p></li><li><span>Projects & installation</span><p>Careful coordination, on site and through handover.</p></li><li><span>Sales & client relationships</span><p>Listening, understanding and helping clients plan.</p></li></ul></section>
    <section class="careers-introduction" id="career-intro"><div class="p-container careers-form-grid"><div><h2>Start with hello.</h2><p>Tell us about your experience and what you would like to contribute. Prepare an introduction you can save or copy.</p><p class="careers-form-note">This form prepares a draft on your device. It does not send an application. Contact our team to confirm the current recruitment channel before sharing your CV.</p><a class="p-text-link" href="/contact/">Contact the team <span aria-hidden="true">›</span></a></div>
    <form id="career-form"><label>Your name<input name="name" autocomplete="name" required maxlength="120"></label><label>Email address<input name="email" type="email" autocomplete="email" required maxlength="200"></label><label>Area of interest<select name="area" required><option value="">Choose an area</option><option>Design & planning</option><option>Engineering & making</option><option>Projects & installation</option><option>Sales & client relationships</option><option>Another area</option></select></label><label>Portfolio or CV link (optional)<input name="portfolio" type="url" placeholder="https://" maxlength="1000"></label><label>A little about you<textarea name="message" rows="5" required maxlength="3000"></textarea></label><button class="p-button" type="submit">Prepare my introduction</button><div id="career-draft" hidden><h3>Your introduction is ready.</h3><textarea id="career-draft-text" rows="9" readonly aria-label="Prepared career introduction"></textarea><div class="p-actions"><button type="button" class="p-button" data-career-copy>Copy introduction</button><button type="button" class="p-text-link" data-career-save>Save introduction</button></div><p id="career-status" role="status"></p></div><noscript><p>Contact the team to ask about careers at Dupedia.</p></noscript></form></div></section></div>'''
    g['page']('/careers/','Careers at Dupedia','Bring your creativity, curiosity and care to Dupedia. Explore areas of work and prepare an introduction to our team.',body,crumbs=[('Home','/'),('Careers','/careers/')])
